CREATE PROCEDURE `plus_one`(`x` INT64) RETURNS `result` INT64 AS {
  RETURN `x` + 1 AS `result`
}

CREATE PROCEDURE `greet`(`name` STRING, `prefix` STRING DEFAULT "hi") RETURNS `message` STRING AS {
  RETURN `prefix` || `name` AS `message`
}

CREATE PROCEDURE `count_incoming_knows`() RETURNS (`id` INT64, `score` INT64) AS {
  NODE VALUE `score` SumAgg<INT64> = 0
  TABLE `result_rows` TYPED TABLE {`id` INT64, `score` INT64} PARTITION BY DEFAULT
  MATCH (`s`@`Person`)-[`e`@`KNOWS`]->(`t`@`Person`)
  PER PATH {
    SET `t`.@`score` += 1
  }
  MATCH (`n`@`Person`)
  PER NODE (`n`) {
    EXPORT `n`.`id`, `n`.@`score` INTO `result_rows`
  }
  PER PARTITION (`part`) OF `result_rows` {
    FOR `row` IN `part`
    RETURN `row`.`id` AS `id`, `row`.`score` AS `score`
  }
}
